import sys, json, uuid, hashlib, datetime

# THE WINDOW OF ONE MODEL (curator, GH #888). This cell decides what the model
# behind the hive sees on every call and keeps the record of what it saw:
#
#   * the hot path (`win-hashes` -> `win`): the system part is the `slots` the
#     ledger holds, sent only when a family changed and then as a `$replace`
#     root; the messages are the wall after the newest summary, in `seq` order,
#     over every session (OR-KX-K4). Deterministic, no model call. Between two
#     rebuilds only the END of the window moves (OR-KX-G4) -- a provider's
#     prefix cache keys on exactly that.
#   * the record: one `calls` row and its `call_blocks` per call, written in
#     the same emission as the call itself, BEFORE the brain has it.
#   * the tap (`tap`): the usage the brain reported fills that row later, and
#     a stamped `cache_expires_at` orders the clock (remove + add, the pattern
#     of `display/compose` -> `display/clock`).
#   * the rebuild (`rb-*`, `sum`): when the cache has gone cold or the prompt
#     crossed `compress_at`, the wall between the last summary and the newest
#     `keep_recent` rounds is condensed by `./summarizer` -- never in the hot
#     path, at most one at a time (OR-KX-K5), and a failed summary leaves the
#     window as it was (OR-KX-K6).
#
# `history_window(rows, params)` is the window as a PURE function of a wall
# sequence: evaluation harnesses load it with the upper-case knob constants via
# `ast`, without running the per-message program (OR-KX-G13).
doc = json.load(sys.stdin)
d = doc.get("body") or {}
envelope = doc.get("envelope") or {}
P = doc.get("params") or {}
header = envelope.get("header") or {}
hop = header.get("hop") or {}
ctx = header.get("context") or {}


def _knob(key, default):
    v = P.get(key, default)
    return default if v is None else v


def _int(key, default):
    v = _knob(key, default)
    if isinstance(v, str) and not v.strip():
        return default
    return int(float(v))


def _float(key, default):
    v = _knob(key, default)
    if isinstance(v, str) and not v.strip():
        return default
    return float(v)


# The knobs. The literal beside each name is the shipped default, the same
# number `params` and `contract.settings` carry (a sweep pins the three).
KEEP_RECENT = _int("keep_recent", 12)
COMPRESS_AT = _float("compress_at", 0.5)
CONTEXT_WINDOW = _int("context_window", 0)
SUMMARY_CHARS = _int("summary_chars", 4000)
SIDECAR_MAX_CHARS = _int("sidecar_max_chars", 6000)

FMT = "%Y-%m-%dT%H:%M:%S.%fZ"
ME = "curator-policy"
# A claimed rebuild older than this is taken to have died with its summarizer
# call (whose own backstop is far below it) and may be claimed again.
REBUILD_STALE_S = 900
# Tool payloads are cut in the summarizer's transcript, never in the window.
TRANSCRIPT_TOOL_CHARS = 2000
NAMESPACE = uuid.UUID("5f0c2a8e-8b1d-4b0e-9a43-0c0a7e6f8801")
SUMMARY_PATH = "history.summary"
SUMMARY_HEAD = ("[earlier exchange, summarised -- what was said, not what is true;"
                " ledger rows up to %d, %s .. %s]")
SUMMARY_PROMPT = (
    "You condense the earlier part of an exchange with a model so that a short text can"
    " stand in for it. Write down what was said, in the order it was said: questions, answers,"
    " decisions, open points, names and numbers as they were given. Report, do not"
    " judge: a statement is not true because it was made, and when a later turn"
    " contradicts an earlier one, keep both. Leave out any identity, persona or standing"
    " instructions of the model; those are kept elsewhere. Answer with the summary text only, in at"
    " most %d characters.")


def canonical(value):
    """The one serialisation a block is hashed and stored in: keys sorted,
    UTF-8, no whitespace."""
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def block_hash(value):
    return hashlib.sha256(canonical(value).encode("utf-8")).hexdigest()


def block_span(text):
    """Where an answer's sidecar block stands: (start, end) or None.

    The boundary is the fence `talky/splitter` cuts (GH #379, #605): the
    ```sidecar fence, or the legacy ```memory fence, to the next closing fence
    or to the end of the text when the completion stopped inside the block.
    Measured, never parsed -- the sections inside are somebody else's business.
    """
    low = text.lower()
    for fence in ("```sidecar", "```memory"):
        at = low.find(fence)
        if at < 0:
            continue
        head = text.find("\n", at)
        close = text.find("```", head + 1) if head >= 0 else -1
        if head >= 0 and close >= 0:
            return at, close + 3
        return at, len(text)
    return None


def stripped_text(text):
    span = block_span(text)
    if span is None:
        return text
    return (text[:span[0]] + text[span[1]:]).strip()


def element_of(row):
    """The element a wall row stands for: `element` when the caller has it,
    else the block body the ledger stored."""
    el = row.get("element")
    if isinstance(el, dict):
        return el
    try:
        el = json.loads(str(row.get("body") or ""))
    except Exception:
        return None
    return el if isinstance(el, dict) else None


def window_items(rows, params=None):
    """(element, hash) of every message of the window, in wall order.

    Two rules, both from what a provider accepts and what the model needs:
    a final answer of the model shows its sidecar block when the block is at
    most `sidecar_max_chars` long and the answer without it otherwise (GH #871:
    without a precedent in the earlier answers the block quote fell from 98 % to
    38 %); and a tool call without its result, or a result without its call, in
    the same turn is left out -- a malformed pair is a refused request for every
    provider."""
    params = params or {}
    cap = params.get("sidecar_max_chars", SIDECAR_MAX_CHARS)
    cap = SIDECAR_MAX_CHARS if cap in (None, "") else int(float(cap))
    ordered = sorted(rows, key=lambda r: int(r.get("seq") or 0))
    calls, results = {}, {}
    for r in ordered:
        el = element_of(r)
        if el is None:
            continue
        key = (str(r.get("session_id") or ""), str(r.get("turn_id") or ""))
        if el.get("type") == "tool_call":
            calls.setdefault(key, set()).add(str(el.get("id") or ""))
        elif el.get("type") == "tool_result":
            results.setdefault(key, set()).add(str(el.get("id") or ""))
    out = []
    for r in ordered:
        el = element_of(r)
        if el is None:
            continue
        key = (str(r.get("session_id") or ""), str(r.get("turn_id") or ""))
        eid = str(el.get("id") or "")
        if el.get("type") == "tool_call" and eid not in results.get(key, set()):
            continue
        if el.get("type") == "tool_result" and eid not in calls.get(key, set()):
            continue
        if str(r.get("kind") or "") == "assistant" and int(r.get("final") or 0) == 1:
            text = str(el.get("text") or "")
            span = block_span(text)
            if span is not None and span[1] - span[0] > cap:
                el = dict(el, text=stripped_text(text))
        out.append((el, block_hash(el)))
    return out


def history_window(rows, params=None):
    """The window messages of a wall sequence (rows with `seq`, `kind`,
    `final`, `session_id`, `turn_id` and `element` or `body`), rule #871
    included. Pure: no I/O, no clock, no state."""
    return [el for el, _ in window_items(rows, params)]


def path_key(path):
    return tuple(path.split("."))


def family_hashes(leaves):
    """One hash per top-level family over its (path, block hash) pairs."""
    fams = {}
    for path, _, h in leaves:
        fams.setdefault(path.split(".")[0], []).append([path, h])
    return {f: block_hash(sorted(v)) for f, v in fams.items()}


def family_node(fam, leaves):
    """A whole family as ONE `$replace` root: every leaf it holds, the
    collector's and the pack's alike -- `$replace` drops the subtree before the
    upsert, so a family is never sent with half its leaves."""
    node = {"$replace": True}
    for path, text, _ in sorted(leaves, key=lambda x: path_key(x[0])):
        parts = path.split(".")
        if parts[0] != fam:
            continue
        if len(parts) == 1:
            node["text"] = text
            continue
        at = node
        for seg in parts[1:-1]:
            at = at.setdefault(seg, {})
        at[parts[-1]] = {"text": text}
    return node


def transcript_line(kind, el):
    text = str(el.get("text") or "")
    if kind in ("tool_call", "recall", "brief"):
        try:
            fn = json.loads(text) or {}
        except Exception:
            fn = {}
        return "assistant called %s(%s)" % (fn.get("name") or "?", fn.get("arguments") or "")
    if kind in ("tool_result",):
        if len(text) > TRANSCRIPT_TOOL_CHARS:
            text = text[:TRANSCRIPT_TOOL_CHARS] + " [cut]"
        return "tool result: " + text
    if kind == "assistant":
        return "assistant: " + stripped_text(text)
    if kind == "peer":
        who = str(el.get("speaker") or el.get("speaker_ref") or "")
        return ("peer %s: " % who if who else "peer: ") + text
    if kind in ("advice", "delegation"):
        return "note: " + text
    return "user: " + text


def rounds_cut(rows, keep):
    """The first `seq` that stays: the first row of the oldest of the newest
    `keep` rounds (a round = one `(session_id, turn_id)`). Rows before it are
    what a rebuild condenses; a cut at a round keeps tool pairs whole."""
    firsts, seen = [], set()
    for r in sorted(rows, key=lambda r: int(r.get("seq") or 0)):
        key = (str(r.get("session_id") or ""), str(r.get("turn_id") or ""))
        if key not in seen:
            seen.add(key)
            firsts.append(int(r.get("seq") or 0))
    if keep <= 0:
        return None
    if len(firsts) <= keep:
        return firsts[0] if firsts else None
    return firsts[-keep]


def now():
    return datetime.datetime.now(datetime.timezone.utc).strftime(FMT)


def now_ms():
    return int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)


def iso_z(ms):
    """Epoch milliseconds as the timer's `at`: RFC 3339, UTC, rounded UP to the
    second -- the timer refuses an `at` that is already past."""
    return datetime.datetime.fromtimestamp(-(-int(ms) // 1000),
                                           datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def epoch_ms(value):
    """A stamped expiry as epoch milliseconds: RFC 3339 text, or a number of
    seconds (milliseconds above 1e12). None when it reads as neither."""
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return int(value if value > 1e12 else value * 1000)
    s = str(value or "").strip()
    if not s:
        return None
    try:
        t = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
    except ValueError:
        return None
    if t.tzinfo is None:
        t = t.replace(tzinfo=datetime.timezone.utc)
    return int(t.timestamp() * 1000)


def emit(msgs):
    sys.stdout.write(json.dumps(msgs))
    sys.exit(0)


def park(reason=""):
    if reason:
        sys.stderr.write("curator/policy: %s\n" % reason)
    emit([])


def lstore(ops, phase, call="", reason=""):
    return {"header": {"route": "lstore", "phase": phase, "reply_cell": ME,
                       "cur_call": call, "cur_reason": reason},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": cid,
                          "text": json.dumps(args)} for cid, args in ops]}


def legs(body):
    out = {}
    for m in body.get("messages") or []:
        if not isinstance(m, dict):
            continue
        try:
            payload = json.loads(m.get("text") or "null")
        except Exception:
            payload = None
        out[str(m.get("id") or "")] = {"payload": payload, "error_code": "",
                                       "rows_affected": 0}
    results = body.get("results")
    if isinstance(results, list):
        for r in results:
            if not isinstance(r, dict):
                continue
            leg = out.setdefault(str(r.get("tool_call_id") or ""),
                                 {"payload": None, "error_code": "", "rows_affected": 0})
            leg["error_code"] = str(r.get("error_code") or "")
            leg["rows_affected"] = int(r.get("rows_affected") or 0)
    elif len(out) == 1:
        leg = next(iter(out.values()))
        leg["error_code"] = str(hop.get("error_code") or "")
        leg["rows_affected"] = int(hop.get("rows_affected") or 0)
    return out


def rows(lg, cid):
    p = (lg.get(cid) or {}).get("payload")
    return p if isinstance(p, list) else []


def sel(table, columns, where=None, order=None, limit=None):
    a = {"operation": "select", "table": table, "columns": columns}
    if where:
        a["where"] = where
    if order:
        a["order_by"] = [{"col": c, "dir": o} for c, o in order]
    if limit:
        a["limit"] = limit
    return a


def ins(table, row):
    return {"operation": "insert", "table": table, "row": row}


def upd(table, values, where):
    return {"operation": "update", "table": table, "set": values, "where": where}


def state_of(lg, cid):
    return {str(r.get("key") or ""): str(r.get("value") or "") for r in rows(lg, cid)}


def loads(text, default):
    try:
        v = json.loads(text)
    except Exception:
        return default
    return v if isinstance(v, type(default)) else default


def schedule_id(call):
    return str(uuid.uuid5(NAMESPACE, "cache:" + call))


def report_errors(lg):
    for cid, leg in lg.items():
        if leg["error_code"]:
            sys.stderr.write("curator/policy: ledger op %s failed: %s\n" % (cid, leg["error_code"]))


def probe(call, reason):
    """The first step of every rebuild: is this trigger current, and is
    another rebuild already running?"""
    return lstore([("p-state", sel("state", ["key", "value"],
                                   {"key": {"in": ["last_call", "rebuild_running"]}})),
                   ("p-sum", sel("summaries", ["id", "covers_to_seq", "hash", "at"], None,
                                 [("covers_to_seq", "desc")], 1))],
                  "rb-probe", call, reason)


# ======================================================================= LANES
lane = str(hop.get("route") or "")
phase = str(ctx.get("cur_phase") or "")
op = str(hop.get("operation") or "")

if lane == "in_cache_expired":
    call = str(d.get("curator_call") or "")
    reason = str(d.get("reason") or "cache")
    msg = probe(call, reason)
    if call:
        # A one-shot that struck is `completed` at the timer; a later `remove`
        # for it answers `schedule_not_found` (it only touches `active` rows,
        # `timer/db.rs` `mark_removed`) -- one stderr line per idle cycle
        # (review M-2). Disarm it, but only if no newer order is armed (CAS).
        msg["messages"].insert(0, {
            "origin": "assistant", "type": "tool_call", "id": "p-disarm",
            "text": json.dumps(upd("state", {"value": ""},
                                   {"key": "armed_call", "value": call}))})
    emit([msg])

if lane == "in_clock_error" or str(hop.get("msg_type") or "") == "timer_op_error":
    code = str(hop.get("error_code") or "")
    if code == "at_in_past":
        # The order came too late for the timer: the cache is cold now.
        emit([probe("", "cache")])
    park("clock refused an order: %s" % (code or "?"))

if lane == "in_summary":
    text = ""
    for m in d.get("messages") or []:
        if isinstance(m, dict) and m.get("origin") == "assistant" and m.get("type") == "text":
            text = str(m.get("text") or "")
            break
    payload = {"text": text, "finish": str(hop.get("finish_reason") or ""),
               "model": str(hop.get("model") or ""), "error_code": str(hop.get("error_code") or "")}
    # One rebuild runs at a time (the lock in `rebuild_running`), so one answer
    # is in flight and a fixed key is enough.
    ops = [("s-clear", {"operation": "delete", "table": "state",
                        "where": {"key": "pending:summary"}}),
           ("s-put", ins("state", {"key": "pending:summary", "value": canonical(payload)})),
           ("s-read", sel("state", ["key", "value"],
                          {"key": {"in": ["rebuild_running", "actions_pending",
                                          "pending:summary"]}}))]
    emit([lstore(ops, "sum", str(ctx.get("cur_call") or ""), str(ctx.get("cur_reason") or ""))])

if lane:
    park("unknown lane %r -- dropped" % lane)

# ================================================================= PHASES
if not op:
    park("a message with neither a lane nor a store answer -- dropped")

lg = legs(d)
call = str(ctx.get("cur_call") or "")
reason = str(ctx.get("cur_reason") or "")

if phase == "done":
    report_errors(lg)
    emit([])

if phase == "win-hashes":
    report_errors(lg)
    covers = rows(lg, "b-cover")
    cover = int(covers[0].get("covers_to_seq") or 0) if covers else 0
    needed = sorted({str(r.get("hash") or "") for r in rows(lg, "b-wallh")}
                    | {str(r.get("hash") or "") for r in rows(lg, "b-slotsh")})
    ops = [("w-wall", sel("wall", ["seq", "session_id", "turn_id", "iter", "kind", "hash",
                                   "nth", "final"], {"seq": {"gt": cover}},
                          [("seq", "asc")])),
           ("w-slots", sel("slots", ["path", "hash", "owner"])),
           ("w-state", sel("state", ["key", "value"],
                           {"key": {"in": ["system_hash_sent", "actions_pending",
                                           "pending:" + call]}}))]
    if needed:
        ops.append(("w-blocks", sel("blocks", ["hash", "kind", "body"],
                                    {"hash": {"in": needed}})))
    emit([lstore(ops, "win", call, "")])

if phase == "win":
    state = state_of(lg, "w-state")
    slim = loads(state.get("pending:" + call, ""), {})
    if not slim:
        park("call %s lost its parked turn -- no call" % call)
    blocks = {}
    for r in rows(lg, "w-blocks"):
        blocks.setdefault(str(r.get("hash") or ""), r)
    wall = []
    for r in rows(lg, "w-wall"):
        b = blocks.get(str(r.get("hash") or ""))
        if b is None:
            sys.stderr.write("curator/policy: wall row %s has no block yet -- left out\n"
                             % r.get("seq"))
            continue
        wall.append(dict(r, body=b.get("body")))
    items = window_items(wall, P)
    leaves = []
    for r in rows(lg, "w-slots"):
        h = str(r.get("hash") or "")
        b = blocks.get(h)
        el = element_of(b) if b else None
        if el is None:
            continue
        leaves.append((str(r.get("path") or ""), str(el.get("text") or ""), h))
    leaves.sort(key=lambda x: path_key(x[0]))
    fams = family_hashes(leaves)
    sent = loads(state.get("system_hash_sent", ""), {})
    changed = sorted(f for f in fams if sent.get(f) != fams[f])
    removed = sorted(f for f in sent if f not in fams)
    system = {}
    for f in changed:
        system[f] = family_node(f, leaves)
    for f in removed:
        system[f] = {"$replace": True}
    pending_actions = state.get("actions_pending", "")
    actions = loads(pending_actions, [])
    if changed or removed:
        actions.append("system:" + ",".join(changed + removed))
    stamp = now()
    session = str(slim.get("session") or "")
    turn = str(slim.get("turn") or "")
    try:
        it = int(str(slim.get("iter") or "0"))
    except ValueError:
        it = 0
    ops = [("f-call", ins("calls", {
        "call_id": call, "session_id": session, "turn_id": turn, "iter": it,
        "trigger": "curate", "started_at": stamp, "model": "", "tokens_prompt": None,
        "tokens_completion": None, "tokens_cached": None, "tokens_cache_write": None,
        "cost": None, "cache_expires_at": "", "system_hash": block_hash(fams),
        "actions": actions}))]
    listed = [h for _, _, h in leaves] + [h for _, h in items]
    for pos, h in enumerate(listed):
        ops.append(("f-b%d" % pos, ins("call_blocks", {"call_id": call, "pos": pos, "hash": h})))
    if changed or removed:
        ops.append(("f-sent", upd("state", {"value": canonical(fams)},
                                  {"key": "system_hash_sent"})))
    if actions and pending_actions not in ("", "[]"):
        # Taken only if nobody added one since it was read.
        ops.append(("f-act", upd("state", {"value": "[]"},
                                 {"key": "actions_pending", "value": pending_actions})))
    ops.append(("f-drop", {"operation": "delete", "table": "state",
                           "where": {"key": "pending:" + call}}))
    head = dict(slim.get("hop") or {})
    head["route"] = "brain"
    head["curator_call"] = call
    for k, v in (("session_id", session), ("turn_id", turn), ("iter", str(it))):
        if k not in head:
            head[k] = v
    out = {"header": head, "messages": [el for el, _ in items]}
    if system:
        out["system"] = system
    if "tool_scope" in slim:
        out["tool_scope"] = slim.get("tool_scope")
    emit([lstore(ops, "done", call, ""), out])

if phase == "tap":
    report_errors(lg)
    state = state_of(lg, "b-state")
    stash = loads(state.get("pending:tap-" + call, ""), {})
    usage = stash.get("usage") or {}
    fields = {}
    for k in ("model", "tokens_prompt", "tokens_completion", "tokens_cached",
              "tokens_cache_write", "cost", "cache_expires_at"):
        if usage.get(k) is not None:
            fields[k] = usage.get(k) if k != "cache_expires_at" else str(usage.get(k))
    if "cost" in fields:
        # `calls.cost` is a `json` column: the llm cell stamps a fraction and
        # the store has no real type, so the number is kept as its JSON text
        # (review M4). Anything that is not a number is not a cost.
        c = fields.pop("cost")
        try:
            if not isinstance(c, bool):
                fields["cost"] = canonical(c if isinstance(c, (int, float)) else float(str(c)))
        except (TypeError, ValueError):
            pass
    ops = [("t-last", upd("state", {"value": call}, {"key": "last_call"}))]
    if fields:
        ops.insert(0, ("t-call", upd("calls", fields, {"call_id": call})))
    cw = usage.get("context_window")
    try:
        cw = int(float(cw)) if cw not in (None, "") else CONTEXT_WINDOW
    except (TypeError, ValueError):
        cw = CONTEXT_WINDOW
    tp = usage.get("tokens_prompt")
    due, why = None, ""
    t_now = now_ms()
    if cw > 0 and isinstance(tp, (int, float)) and tp >= COMPRESS_AT * cw:
        # The prompt crossed the line: rebuild now -- through the clock, so the
        # rebuild starts on a message of its own and the call that crossed the
        # line is already on its way.
        due, why = t_now + 1000, "compress"
    else:
        expiry = epoch_ms(usage.get("cache_expires_at"))
        if expiry is not None:
            # A stamp already past (at_in_past) is a cold cache NOW: the earliest
            # second the timer accepts.
            due, why = max(expiry, t_now + 1000), "cache"
    clock = []
    if due is not None:
        armed = state.get("armed_call", "")
        if armed and armed != call:
            clock.append({"header": {"route": "clock"}, "messages": [], "op": "remove",
                          "schedule_id": schedule_id(armed)})
        clock.append({"header": {"route": "clock"}, "messages": [], "op": "add",
                      "schedule_id": schedule_id(call), "schedule_name": "cache",
                      "at": iso_z(due), "emit_to": "../policy",
                      "emit_body": {"messages": [], "curator_call": call, "reason": why}})
        ops.append(("t-armed", upd("state", {"value": call}, {"key": "armed_call"})))
    emit([lstore(ops, "done", call, "")] + clock)

if phase == "rb-probe":
    state = state_of(lg, "p-state")
    if call and call != state.get("last_call", ""):
        park("a fire for call %s, the last call is %s -- stale, dropped"
             % (call, state.get("last_call", "")))
    running = state.get("rebuild_running", "")
    if running:
        info = loads(running, {})
        started = epoch_ms(info.get("at")) or 0
        if now_ms() - started < REBUILD_STALE_S * 1000:
            park("a rebuild is running -- this trigger (%s) merges into it" % reason)
    prev = (rows(lg, "p-sum") or [{}])[0]
    claim = canonical({"reason": reason, "token": str(uuid.uuid4()), "at": now(),
                       "call": call,
                       "prev": {"id": str(prev.get("id") or ""),
                                "hash": str(prev.get("hash") or ""),
                                "covers_to_seq": int(prev.get("covers_to_seq") or 0)}})
    cover = int(prev.get("covers_to_seq") or 0)
    ops = [("c-claim", upd("state", {"value": claim},
                           {"key": "rebuild_running", "value": running})),
           ("c-me", sel("state", ["key", "value"], {"key": "rebuild_running"})),
           ("c-wall", sel("wall", ["seq", "session_id", "turn_id", "kind", "hash", "nth",
                                   "final", "at"], {"seq": {"gt": cover}}, [("seq", "asc")])),
           ("c-slot", sel("slots", ["path"], {"path": SUMMARY_PATH}))]
    emit([lstore(ops, "rb-claim", call, reason)])

if phase == "rb-claim":
    if (lg.get("c-claim") or {}).get("rows_affected", 0) != 1:
        park("another trigger claimed the rebuild first -- merged")
    me = str((rows(lg, "c-me") or [{}])[0].get("value") or "")
    info = loads(me, {})
    wall = rows(lg, "c-wall")
    cut = rounds_cut(wall, KEEP_RECENT)
    todo = [r for r in wall if cut is None or int(r.get("seq") or 0) < cut]
    if KEEP_RECENT > 0 and cut is None:
        todo = []
    if not todo:
        emit([lstore([("r-free", upd("state", {"value": ""},
                                     {"key": "rebuild_running", "value": me}))],
                     "done", call, reason)])
    prev = info.get("prev") or {}
    sources = ([prev["hash"]] if prev.get("hash") else []) + [str(r.get("hash") or "")
                                                              for r in todo]
    info.update({"covers_to_seq": max(int(r.get("seq") or 0) for r in todo),
                 "sources": sources,
                 "kinds": [str(r.get("kind") or "") for r in todo],
                 "first_at": str(todo[0].get("at") or ""),
                 "last_at": str(todo[-1].get("at") or ""),
                 "slot_exists": bool(rows(lg, "c-slot"))})
    note = canonical(info)
    ops = [("n-note", upd("state", {"value": note}, {"key": "rebuild_running", "value": me})),
           ("n-me", sel("state", ["key", "value"], {"key": "rebuild_running"})),
           ("n-blocks", sel("blocks", ["hash", "kind", "body"],
                            {"hash": {"in": sorted(set(sources))}}))]
    emit([lstore(ops, "rb-blocks", call, reason)])

if phase == "rb-blocks":
    info = loads(str((rows(lg, "n-me") or [{}])[0].get("value") or ""), {})
    if not info.get("sources"):
        park("the rebuild note is gone -- dropped")
    blocks = {}
    for r in rows(lg, "n-blocks"):
        blocks.setdefault(str(r.get("hash") or ""), r)
    prev = info.get("prev") or {}
    lines = []
    sources = list(info.get("sources") or [])
    if prev.get("hash") and sources and sources[0] == prev["hash"]:
        el = element_of(blocks.get(sources.pop(0)) or {})
        if el is not None:
            lines.append("Summary of the exchange before this part:\n"
                         + str(el.get("text") or ""))
            lines.append("")
    kinds = list(info.get("kinds") or [])
    for h, kind in zip(sources, kinds):
        el = element_of(blocks.get(h) or {})
        if el is not None:
            lines.append(transcript_line(kind, el))
    emit([{"header": {"route": "summarize"},
           "system": {"instructions": {"text": SUMMARY_PROMPT % SUMMARY_CHARS}},
           "messages": [{"origin": "user", "type": "text", "text": "\n".join(lines)}]}])

if phase == "sum":
    state = state_of(lg, "s-read")
    raw = state.get("rebuild_running", "")
    info = loads(raw, {})
    payload = loads(state.get("pending:summary", ""), {})
    drop = ("s-drop", {"operation": "delete", "table": "state",
                       "where": {"key": "pending:summary"}})
    if not info.get("sources"):
        emit([lstore([drop], "done", call, reason)])
    free = ("s-free", upd("state", {"value": ""}, {"key": "rebuild_running", "value": raw}))
    pending_actions = state.get("actions_pending", "")
    actions = loads(pending_actions, [])
    text = str(payload.get("text") or "")
    why = str(info.get("reason") or reason or "cache")
    failure = ""
    if payload.get("finish") != "stop":
        failure = "finish_reason %s %s" % (payload.get("finish") or "?",
                                          payload.get("error_code") or "")
    elif not text.strip():
        failure = "an empty summary"
    elif len(text) > SUMMARY_CHARS:
        failure = "%d characters, over summary_chars %d" % (len(text), SUMMARY_CHARS)
    if failure:
        # OR-KX-K6: the window stays what it was; the next call says so.
        sys.stderr.write("curator/policy: rebuild (%s) failed: %s -- old window kept\n"
                         % (why, failure.strip()))
        actions.append("rebuild_failed")
        emit([lstore([free, ("s-act", upd("state", {"value": canonical(actions)},
                                          {"key": "actions_pending",
                                           "value": pending_actions})), drop],
                     "done", call, reason)])
    stamp = now()
    summary = {"type": "summary", "text": text}
    h = block_hash(summary)
    sid = str(uuid.uuid4())
    covers = int(info.get("covers_to_seq") or 0)
    rendered = (SUMMARY_HEAD % (covers, info.get("first_at") or "?", info.get("last_at") or "?")
                + "\n" + text)
    slot_el = {"path": SUMMARY_PATH, "text": rendered}
    sh = block_hash(slot_el)
    ops = [("s-b1", ins("blocks", {"hash": h, "kind": "summary", "chars": len(text),
                                   "body": canonical(summary), "first_seen": stamp})),
           ("s-b2", ins("blocks", {"hash": sh, "kind": "system", "chars": len(rendered),
                                   "body": canonical(slot_el), "first_seen": stamp})),
           ("s-row", ins("summaries", {"id": sid, "covers_to_seq": covers, "hash": h,
                                       "sources": info.get("sources") or [],
                                       "model": str(payload.get("model") or ""), "at": stamp}))]
    if info.get("slot_exists"):
        ops.append(("s-slot", upd("slots", {"hash": sh, "owner": "curator", "at": stamp},
                                  {"path": SUMMARY_PATH})))
    else:
        ops.append(("s-slot", ins("slots", {"path": SUMMARY_PATH, "hash": sh,
                                            "owner": "curator", "at": stamp})))
    actions += ["rebuild:" + why, "summary:" + sid]
    ops += [("s-act", upd("state", {"value": canonical(actions)},
                          {"key": "actions_pending", "value": pending_actions})),
            free, drop]
    emit([lstore(ops, "done", call, reason)])

park("store answer in unknown phase %r -- dropped" % phase)
